}

const PRS = [
  { n: 4885, author: 'athosmartins', hint: 'bd history via long-timeout connection (ga-ahnxx). Cross-check overlap/conflict with mohamedramadan14 PRs 4912/4910 which also change bd history.' },
  { n: 4884, author: 'athosmartins', hint: 'wire --label-regex into query pipeline + register on bd ready. SUPERSESSION SUSPECT: upstream #3971 (merged 2026-07-23, "LabelPattern + LabelRegex + JSON truncation hint suppression") may have landed equivalent functionality — compare the merged diff against this PR before any verdict; if superseded, retire-with-credit per guidelines.' },
  { n: 4882, author: 'athosmartins', hint: 'wire --label-pattern into WHERE builder. Same supersession suspect as 4884: compare against merged #3971.' },
  { n: 4865, author: 'athosmartins', hint: 'flag comment_count as omitted when comments not streamed in bd show.' },
  { n: 4393, author: 'athosmartins', hint: 'old PR (pre-June): Dolt /tmp/mysql.sock down -> TCP fallback (gt-28itz). Likely far behind main; check whether socket-fallback behavior changed on main since, and whether a re-cut is cheaper than a rebase.' },
  { n: 4912, author: 'mohamedramadan14', hint: 'coalesce NULL text columns in dolt_history_issues scan. Cross-check overlap with 4885 and 4910.' },
  { n: 4910, author: 'mohamedramadan14', hint: 'resolve partial/short issue IDs in bd history. Cross-check overlap with 4912 (same command surface).' },
  { n: 4909, author: 'mohamedramadan14', hint: 'accurate create/update/skip counts for bd import --dry-run. Check against recently merged import fixes (#4963 #4964, #4029 issue_prefix sync).' },
]

const TARGET = budget.total ?? 200_000
const START = budget.spent() // budget pool is turn-wide; guard on this workflow's own delta

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    pr: { type: 'integer' },
    classification: { type: 'string', enum: ['merge', 'merge-fix', 'fix-merge', 'easy-win', 'retire', 'reject', 'needs-author', 'needs-deeper-review'] },
    maintainer_can_edit: { type: 'boolean' },
