    risk: { type: 'string', enum: ['low', 'medium', 'high'] },
  },
  required: ['pr', 'classification', 'maintainer_can_edit', 'behind_main', 'changes_requested_state', 'supersession', 'findings', 'action_plan', 'risk'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    pr: { type: 'integer' },
    verdict: { type: 'string', enum: ['confirm', 'revise'] },
    reason: { type: 'string' },
