      log(`budget guard: skipping verify for PR ${p.n}`)
      return { review: rev, verdict: { pr: p.n, verdict: 'revise', reason: 'unverified (budget guard) — orchestrator must verify before acting' } }
    }
    return agent(
      `Adversarially verify a maintainer PR assessment for gastownhall/beads PR #${p.n} (author ${p.author}).

The assessment: ${JSON.stringify(rev)}

Try to refute it. Priorities: (a) if it claims CHANGES_REQUESTED items are addressed, check the actual threads and current branch content; (b) if it recommends merge/fix-merge, hunt for a disqualifying problem it missed — correctness, platform breakage, or overlap/conflict with main or with the OTHER in-flight PRs of this sweep (4885/4912/4910 all touch bd history); (c) if it recommends retire, verify the supersession claim by comparing actual diffs — retiring live contributor value is the costly error; also check whether the PR contains anything unique the merged work lacks; (d) check maintainer_can_edit and mergeability claims. Verdict 'revise' with corrections if anything material is wrong; otherwise 'confirm'.

${RULES}`,
      { label: `verify:${p.n}`, phase: 'Verify', schema: VERDICT_SCHEMA }
    ).then((v) => ({ review: rev, verdict: v }))
  }
)

log(`spent ~${Math.round((budget.spent() - START) / 1000)}k of ${Math.round(TARGET / 1000)}k target (this workflow)`)
return { reviews: reviews.filter(Boolean) }

